<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card" style="max-width:650px;margin:0 auto;"><div class="card-header"><h1>Your Complaints</h1><p>Submit and track your complaints.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?><form method="post" action="<?php echo e(url_for('customer','complaints'));?>"><?php echo csrf_field();?><div class="field"><label>Complaint Message</label><textarea name="message" rows="3"><?php echo e($message);?></textarea></div><button class="btn btn-primary btn-block">Submit Complaint</button></form></div>
<div class="card"><div class="card-header"><h2>History</h2></div><?php if(!$my):?><p class="muted">No complaints yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Message</th><th>Status</th><th>Admin Reply</th><th>Date</th></tr><?php foreach($my as $c):?><tr><td>#<?php echo e($c['id']);?></td><td><?php echo e($c['message']);?></td><td><?php echo e($c['status']);?></td><td><?php echo $c['reply']?e($c['reply']):'<span class="muted">— pending —</span>';?></td><td class="small"><?php echo e($c['created_at']);?></td></tr><?php endforeach;?></table><?php endif;?></div>
